-- Refer to https://wiki.hypr.land/Configuring/Basics/Variables/
local palette = require("hypr_palette") -- generated by palette/generate.py

hl.config({
    general = {
        -- 6px between any two things, screen edges and bar included (owner, 2026-10-15: outer
        -- gaps once the wallpaper went in; the spec had 4 between and 0 at the edges).
        gaps_in  = 3, -- per window edge: two neighbours end up 6px apart
        gaps_out = 6,

        -- 2px border: amber on the focused window, muted on the rest. No dimming.
        border_size = 2,
        col = {
            active_border   = palette.accent,
            inactive_border = palette.border,
        },

        -- Set to true to enable resizing windows by clicking and dragging on borders and gaps
        resize_on_border = false,

        -- Please see https://wiki.hypr.land/Configuring/Advanced-and-Cool/Tearing/ before you turn this on
        allow_tearing = false,

        layout = "dwindle",
    },

    -- Sharp, flat, solid: no rounding, no shadow, no blur, no transparency.
    decoration = {
        rounding       = 0,
        rounding_power = 2,

        -- Change transparency of focused and unfocused windows
        active_opacity   = 1.0,
        inactive_opacity = 1.0,

        shadow = {
            enabled      = false,
            range        = 4,
            render_power = 3,
            color        = 0xee1a1a1a,
        },

        blur = {
            enabled   = false,
            size      = 3,
            passes    = 1,
            vibrancy  = 0.1696,
        },
    },

    animations = {
        enabled = true,
    },
})

-- Animations: https://wiki.hypr.land/Configuring/Advanced-and-Cool/Animations/
-- Motion: minimal. Workspace switches, window moves, border color and shell layers
-- are instant. The one motion left is a 120ms linear fade when windows open or close.
hl.curve("linear", { type = "bezier", points = { {0, 0}, {1, 1} } })
hl.animation({ leaf = "workspaces", enabled = false })
hl.animation({ leaf = "windows",    enabled = false })
hl.animation({ leaf = "border",     enabled = false })
hl.animation({ leaf = "layers",     enabled = false })
hl.animation({ leaf = "fade",       enabled = true,  speed = 1.2, bezier = "linear" })
hl.animation({ leaf = "fadeLayers", enabled = false })

